```cpp
struct Node{
	int l;
	int r;
	int sum;
	int lz;
}tr[N << 2];
void pushup(int u){
	tr[u].sum = tr[u << 1].sum + tr[u << 1 | 1].sum;
}
void pushdown(int u){
    tr[u << 1].sum += (tr[u << 1].r - tr[u << 1].l + 1) * tr[u].lz;
    tr[u << 1].lz += tr[u].lz;
    tr[u << 1 | 1].sum += (tr[u << 1 | 1].r - tr[u << 1 | 1].l + 1) * tr[u].lz;
    tr[u << 1 | 1].lz += tr[u].lz;
    tr[u].lz = 0;
}
void build(int l, int r, int u){
    tr[u] = {l, r, 0, 0};
	if(l == r){
		tr[u].sum = a[l];
		return;
	}
	int mid = l + r >> 1;
	build(l, mid, u << 1);
	build(mid + 1, r, u << 1 | 1);
	tr[u].sum = tr[u << 1].sum + tr[u << 1 | 1].sum;
}
void modify(int l, int r, int u, int d){
	if(tr[u].l >= l && tr[u].r <= r){
		tr[u].sum += (tr[u].r - tr[u].l + 1) * d;
		tr[u].lz += d;
        return;
	}
    int mid = tr[u].l + tr[u].r >> 1; 
    pushdown(u);
    if(l <= mid) modify(l, r, u << 1, d);
    if(r >= mid + 1) modify(l, r, u << 1 | 1, d);
    pushup(u);
}
int query(int l, int r, int u){
	if(tr[u].l >= l && tr[u].r <= r){
		return tr[u].sum;
	}
	pushdown(u);
	int sum = 0;
	int mid = tr[u].l + tr[u].r >> 1; 
	if(l <= mid) sum += query(l, r, u << 1);
	if(r >= mid + 1) sum += query(l, r, u << 1 | 1);
	return sum;
}
```
