int MgRT[N];
struct Node{
	int ls, rs, sum;
}tr[N * 40];
void pushup(int u){
	tr[u].sum = tr[tr[u].ls].sum + tr[tr[u].rs].sum;
}
void modify(int &u, int l, int r, int p, int x){
	if(!u) u = ++tot;
	if(l == r){
		tr[u].sum += x; 
		return;
	}
	int mid = l + r >> 1;
	if(p <= mid) modify(tr[u].ls, l, mid, p, x);
	else modify(tr[u].rs, mid + 1, r, p, x);
	pushup(u);
}
int query(int u, int l, int r, int ql, int qr){
	if(ql <= l && r <= qr) return tr[u].sum;
	int mid = l + r >> 1;
	int res = 0;
	if(ql <= mid) res += query(tr[u].ls, l, mid, ql, qr);
	if(qr >= mid + 1) res += query(tr[u].rs, mid + 1, r, ql, qr);
	return res;
}
