int MgRT[N], tot;
struct Node{
	int ls, rs, cnt;
}tr[N * 40];
void pushup(int u){
	tr[u].cnt = tr[tr[u].ls].cnt + tr[tr[u].rs].cnt;
}
void modify(int &u, int l, int r, int p){
	tr[++tot] = tr[u];
	u = tot;
	if(l == r){
		tr[u].cnt++;
		return;
	}
	int mid = l + r >> 1;
	if(p <= mid) modify(tr[u].ls, l, mid, p);
	else modify(tr[u].rs, mid + 1, r, p);
	pushup(u);
}
int query(int x, int y, int l, int r, int k){
	if(l == r) return l;
	int mid = l + r >> 1, sum = tr[tr[y].ls].cnt - tr[tr[x].ls].cnt;
	if(sum >= k) return query(tr[x].ls, tr[y].ls, l, mid, k);
	else return query(tr[x].rs, tr[y].rs, mid + 1, r, k - sum);
}
