struct Node{
	int ls, rs;
    ll cnt;
}tr[N * 60];
int idx, top, rub[N * 60], rt[N], siz[N];
int new_node(){
	if(top) return rub[top--];
	return ++idx;
}
void del(int &u){
	rub[++top] = u;
	tr[u].cnt = tr[u].ls = tr[u].rs = 0;
	u = 0;
}
void pushup(int u){
	tr[u].cnt = tr[tr[u].ls].cnt + tr[tr[u].rs].cnt;
}
void modify(int &u, int l, int r, int p, ll v){
	if(!u) u = new_node();
	if(l == r){
		tr[u].cnt += v;
		return; 
	}
	int mid = l + r >> 1;
	if(p <= mid) modify(tr[u].ls, l, mid, p, v);
	else modify(tr[u].rs, mid + 1, r, p, v);
	pushup(u);
	return;
}
ll query(int u, int l, int r, int ql, int qr){
	if(!u) return 0;
	if(ql <= l && r <= qr) return tr[u].cnt;
	int mid = l + r >> 1;
	ll sum = 0;
	if(ql <= mid) sum += query(tr[u].ls, l, mid, ql, qr);
	if(qr >= mid + 1) sum += query(tr[u].rs, mid + 1, r, ql, qr);
	return sum;
}
int kth(int u, int l, int r, ll k){
	if(l == r) return l;
	int mid = l + r >> 1;
	int lcnt = tr[tr[u].ls].cnt;
	if(k <= lcnt) return kth(tr[u].ls, l, mid, k);
	else return kth(tr[u].rs, mid + 1, r, k - lcnt);
}
int merge(int x, int y){
	if(!x || !y) return x + y;
	tr[x].cnt += tr[y].cnt;
	tr[x].ls = merge(tr[x].ls, tr[y].ls);
	tr[x].rs = merge(tr[x].rs, tr[y].rs);
	del(y);
	return x;
}
void split(int &x, int &y, int k){
	if(!x) return;
    if (k == 0) { y = x; x = 0; return; }
    if (k >= tr[x].cnt) { y = 0; return; }
	y = new_node();
	int cnt = tr[tr[x].ls].cnt;
	int xcnt = tr[x].cnt;
	if(k < cnt){
		tr[y].rs = tr[x].rs;
		tr[x].rs = 0;
		split(tr[x].ls, tr[y].ls, k);
	}else if(k == cnt){
		tr[y].rs = tr[x].rs;
		tr[x].rs = 0;		
	}else{
		split(tr[x].rs, tr[y].rs, k - cnt);
	}
	tr[y].cnt = xcnt - k;
	tr[x].cnt = k;
}
