线段树合并
::::success[code]
```cpp
struct Node{
    int ls, rs;
    int cnt;
    int id;
} tr[N * 60];
int idx, top, rub[N * 60], rt[N];
int new_node(){
    if(top) return rub[top--];
    return ++idx;
}
void del(int &u){
    rub[++top] = u;
    tr[u].cnt = tr[u].ls = tr[u].rs = tr[u].id = 0;
    u = 0;
}
void pushup(int u){
    int l = tr[u].ls, r = tr[u].rs;
    if(tr[l].cnt > tr[r].cnt){
        tr[u].cnt = tr[l].cnt;
        tr[u].id = tr[l].id;
    }else if(tr[l].cnt < tr[r].cnt){
        tr[u].cnt = tr[r].cnt;
        tr[u].id = tr[r].id;
    }else{
        tr[u].cnt = tr[l].cnt;
        tr[u].id = min(tr[l].id, tr[r].id);
    }
}
void modify(int &u, int l, int r, int p, int v){
    if(!u) u = new_node();
    if(l == r){
        tr[u].cnt += v;
        tr[u].id = l;
        return;
    }
    int mid = (l + r) >> 1;
    if(p <= mid) modify(tr[u].ls, l, mid, p, v);
    else modify(tr[u].rs, mid + 1, r, p, v);
    pushup(u);
}
int merge(int x, int y){
    if(!x || !y) return x + y;
    if(tr[x].ls == 0 && tr[x].rs == 0){
        tr[x].cnt += tr[y].cnt;
        tr[x].id = tr[y].id;
        del(y);
        return x;
    }
    tr[x].ls = merge(tr[x].ls, tr[y].ls);
    tr[x].rs = merge(tr[x].rs, tr[y].rs);
    pushup(x);
    del(y);
    return x;
}
