	int x;
	int yy1, yy2;
	int k;
}seg[N * 2]; 
vector<int> ys;
struct Node{
	int l;
	int r;
	int cnt;
	int len;
}t[N * 8];
bool operator <(const sg x, const sg y){
	return x.x < y.x;
}
int find(double y){
    return lower_bound(ys.begin(), ys.end(), y) - ys.begin();
}
void pushup(int u){
	if(t[u].cnt){
		t[u].len = ys[t[u].r + 1] - ys[t[u].l];
	}else if(t[u].l != t[u].r){
		t[u].len = t[u << 1].len + t[u << 1 | 1].len;
	}else{
		t[u].len = 0;
	} 
}
void build(int l, int r, int u){
	t[u] = Node{l, r, 0, 0};
	if(l != r){
		int mid = l + r >> 1;
		build(l, mid, u << 1);
		build(mid + 1, r, u << 1 | 1);
	}
}
void modify(int l, int r, int u, int k){
	if(t[u].l >= l && t[u].r <= r){
		t[u].cnt += k;
		pushup(u);
		return;
	}
	int mid = t[u].l + t[u].r >> 1;
	if(l <= mid) modify(l, r, u << 1, k);
	if(r >= mid + 1)modify(l, r, u << 1 | 1, k);
	pushup(u);
}
