		seg[j ++] = sg{xx1, yy1, yy2, 1};
		seg[j ++] = sg{xx2, yy1, yy2, -1};
		ys.push_back(yy1);
		ys.push_back(yy2);
	}
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    build( 0, ys.size() - 2, 1);
    sort(seg, seg + n * 2);
	int res = 0;
	for(int i = 0; i < 2 * n; i++){
		if(i > 0) res += t[1].len * (seg[i].x - seg[i-1].x);
		int k1 = find(seg[i].yy1);
		int k2 = find(seg[i].yy2);
		modify(k1, k2 - 1, 1, seg[i].k);
	}
	cout << res << "\n";
	return 0;
}
