int lowbit(int x){ return x & -x; }
void add(int x, int k){
    while(x <= n){
        BIT[x] += k;
        x = x + lowbit(x);
    }
}
int ask(int x){
    int res = 0;
    while(x){
        res = res + BIT[x];
        x = x - lowbit(x);
    }
    return res;
}
