普通平衡树
::::success[code]
```cpp
struct Node{
	int ls, rs, val, rnd, cnt, siz;
}tr[N];
int idx, rt;
int new_node(int v){
	tr[++idx] = {0, 0, v, (int)rng(), 1, 1};
	return idx;
}
void pushup(int u){
	tr[u].siz = tr[tr[u].ls].siz + tr[tr[u].rs].siz + tr[u].cnt;
}
void split(int &x, int &y, int u, int k){
	if(!u){
		x = y = 0;
		return;
	}
	if(tr[u].val <= k){
		x = u;
		split(tr[u].rs, y, tr[u].rs, k);
	}else{
		y = u;
		split(x, tr[u].ls, tr[u].ls, k);
	}
	pushup(u);
}
int merge(int x, int y){
	if(!x || !y) return x + y;
	if(tr[x].rnd > tr[y].rnd){
		tr[x].rs = merge(tr[x].rs, y);
		pushup(x);
		return x;
	}else{
		tr[y].ls = merge(x, tr[y].ls);
		pushup(y);
		return y;
	}
}
```
