```cpp
struct Node{
    int ls, rs, rev, siz, val, rnd;
}tr[N];
int idx, rt, n, m;
int new_node(int v){ tr[++idx] = {0, 0, 0, 1, v, (int)rng()}; return idx; }
void pushup(int u){ tr[u].siz = tr[tr[u].ls].siz + tr[tr[u].rs].siz + 1; }
void pushdown(int u){
    if(!tr[u].rev) return;
    swap(tr[u].ls, tr[u].rs);
    tr[tr[u].ls].rev ^= 1, tr[tr[u].rs].rev ^= 1, tr[u].rev = 0;
}
void split(int u, int k, int &x, int &y){
    if(!u){ x = y = 0; return; }
    pushdown(u);
    if(tr[tr[u].ls].siz >= k){
        y = u;
        split(tr[u].ls, k, x, tr[u].ls);
        pushup(y);
    }else{
        x = u;
        split(tr[u].rs, k - tr[tr[u].ls].siz - 1, tr[u].rs, y);
        pushup(x);
    }
}
int merge(int x, int y){
    if(!x || !y) return x + y;
    if(tr[x].rnd > tr[y].rnd){
        pushdown(x);
        tr[x].rs = merge(tr[x].rs, y);
        pushup(x);
        return x;
    }else{
        pushdown(y);
        tr[y].ls = merge(x, tr[y].ls);
        pushup(y);
        return y;
    }
}
void rev(int l, int r){
    int a, b, c, d, e;
    split(rt, l - 1, a, b);
    split(b, r - l + 1, c, d);
    tr[c].rev ^= 1;
    e = merge(c, d);
    rt = merge(a, e);
}
void dfs(int u){
    if(!u) return;
    pushdown(u);
    dfs(tr[u].ls);
    cout << tr[u].val << " ";
    dfs(tr[u].rs);
}
