struct Node{
	int l, r, t, lk, rk, ans, p;
}q[N]; 
int opp[N], opc[N], cnt[N];
int id, B, ct;
bool cmp(Node x, Node y){
	if(x.lk == y.lk){
		if(x.rk == y.rk) return x.t < y.t;
		return x.rk < y.rk;
	}
	return x.lk < y.lk;
}
bool cmp2(Node x, Node y){
	return x.p < y.p;
}
void add(int x, int &res){
	cnt[x]++;
	if(cnt[x] == 1) res++;
}
void del(int x, int &res){
	cnt[x]--;
	if(cnt[x] == 0) res--;
}
void md(){
	int L = 1, R = 0, T = 0; 
	int ans = 0;
	for(int i = 1; i <= ct; i++){
		int l = q[i].l, r = q[i].r, t = q[i].t;
		while(R < r){R++; add(col[R], ans);}
		while(L > l){L--; add(col[L], ans);}
		while(R > r){R--; del(col[R+1], ans);}
		while(L < l){L++; del(col[L-1], ans);}
		while(T < t){
			T++;
			if(opp[T] >= L && opp[T] <= R){
				del(col[opp[T]], ans);
				add(opc[T], ans);
			}
			swap(col[opp[T]], opc[T]);
		}
		while(T > t){
			T--;
			if(opp[T+1] >= L && opp[T+1] <= R){
				del(col[opp[T+1]], ans);
				add(opc[T+1], ans);
			}
			swap(col[opp[T+1]], opc[T+1]);
		}
		q[i].ans = ans;
