void cdq(int l, int r){
	if(l == r) return;
	for(int i = l; i <= r; i++) b[i] = a[i];
	int mid = l + r >> 1;
	sort(b + l, b + mid + 1, cmp);
	sort(b + mid + 1, b + r + 1, cmp); 
	int pl = l, pr = mid + 1;
	int lcnt = 0;
	while(pl <= mid || pr <= r){
		if(pl > mid) ans[m - b[pr].t + 2 + n] += ask(b[pr].t), pr++;
		else if(pr > r) add(b[pl].t, 1), ls[++lcnt] = b[pl].t, pl++;
		else if(b[pr].val > b[pl].val) ans[m - b[pr].t + 2 + n] += ask(b[pr].t), pr++;
		else add(b[pl].t, 1), ls[++lcnt] = b[pl].t, pl++;
	}
	for(int i = 1; i <= lcnt; i++) add(ls[i], -1);
	cdq(l, mid);
	cdq(mid + 1, r);
}
