struct Node{
	int x, y, k, id, type;
}q[N << 1], q1[N << 1], q2[N << 1];
void add(int x, int y){
	while(x <= n){
		tr[x] += y;
		x += lowbit(x);
	}
}
int query(int x){
	int res = 0;
	while(x){
		res += tr[x];
		x -= lowbit(x);
	}
	return res;
}
void solve(int ql, int qr, int l, int r){
	if(ql > qr) return;
	if(l == r){
		for(int i = ql; i <= qr; i++) if(q[i].type) ans[q[i].id] = l;
		return;		
	}
	int mid = l + r >> 1, c1 = 0, c2 = 0;
	for(int i = ql; i <= qr; i++){
		if(!q[i].type){
			if(q[i].x <= mid){
				add(q[i].id, 1);
				q1[++c1] = q[i];
			}
			else q2[++c2] = q[i];
		}
	}
    for(int i = ql; i <= qr; i++){
        if(q[i].type){
			int tmp = query(q[i].y) - query(q[i].x-1);
			if(q[i].k <= tmp) q1[++c1] = q[i];
			else q[i].k -= tmp, q2[++c2] = q[i];
		}
    }
	for(int i = 1; i <= c1; i++) if(!q1[i].type) add(q1[i].id, -1);
	for(int i = 1; i <= c1; i++) q[i + ql - 1] = q1[i];
	for(int i = 1; i <= c2; i++) q[i + ql + c1 - 1] = q2[i];
	solve(ql, ql + c1 - 1, l, mid);
	solve(ql + c1, qr, mid + 1, r); 
}
