	modify(mgrt1[u], 0, n, 0, x);
	for(int f = u; fa[f] != 0; f = fa[f]){
		int d = get_dis(fa[f], u);
		modify(mgrt1[fa[f]], 0, n, d, x);
		modify(mgrt2[f], 0, n, d, x);
	}
