int ask(int x, int k){
	int ans = query(mgrt1[x], 0, n, 0, k);
	for(int f = x; fa[f] != 0; f = fa[f]){
		int d = get_dis(fa[f], x);
		if(k - d < 0) continue;
		ans += query(mgrt1[fa[f]], 0, n, 0, k - d) - query(mgrt2[f], 0, n, 0, k - d);
	}
	return ans;
}
