priority_queue<P> q;
void dij(int s){
	memset(d, 0x3f, sizeof d);
	d[s] = 0;
	q.push(P{s, 0});
	while(!q.empty()){
		P u = q.top();
		q.pop();
		if(in[u.id]) continue;
		in[u.id] = 1;
		for(auto v : e[u.id]){
			if(v.val + d[u.id] < d[v.to]){
				d[v.to] = v.val + d[u.id];
				q.push(P{v.to, d[v.to]});
			}
		}
	}
