#include <bits/stdc++.h>

using namespace std;
const int N = 1e6 + 10, inf = 1e9;
int vis[N], cnt[N], T, n, ans = 0;
struct Node{
	int l, r, mn, lz;
}tr[N << 2];
void pushdown(int u){
	int &lz = tr[u].lz;
	tr[u << 1].mn += lz, tr[u << 1].lz += lz, tr[u << 1 | 1].mn += lz, tr[u << 1 | 1].lz += lz;
	lz = 0;
}
void pushup(int u){
	tr[u].mn = min(tr[u << 1].mn, tr[u << 1 | 1].mn);
}
void build(int u, int l, int r){
	tr[u] = {l, r, 0, 0};
	if(l == r) return;
	int mid = l + r >> 1;
	build(u << 1, l, mid);
	build(u << 1 | 1, mid + 1, r);
}
void modify(int u, int l, int r, int x){
	if(l <= tr[u].l && tr[u].r <= r){
		tr[u].mn += x;
		tr[u].lz += x;
		return;
	}
	int mid = tr[u].l + tr[u].r >> 1;
	pushdown(u);
	if(l <= mid) modify(u << 1, l, r, x);
	if(r >= mid + 1) modify(u << 1 | 1, l, r, x);
	pushup(u);
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> T;
	while(T--){
		cin >> n;
		ans = 0;
		for(int i = 0; i <= n; i++) vis[i] = cnt[i] = 0;
		build(1, 0, n);
		for(int i = 1; i <= n; i++){
			int x;
			cin >> x;
			if(x < ans && vis[x] == 0) modify(1, 0, x, 1), vis[x] = 1;
			else{
				if(x <= n) cnt[x]++;
				modify(1, 0, (x - 1) / 2, 1);
			} 
			while(ans <= i){
				if(vis[ans] == 1) ans++;
				else if(cnt[ans] >= 1){
					modify(1, 0, (ans - 1) / 2, -1);
					if(tr[1].mn >= 0) cnt[ans]--, vis[ans] = 1, ans++;
					else{
						modify(1, 0, (ans - 1) / 2, 1);
						break;
					}
				}else{
					modify(1, 0, ans, -1);
					if(tr[1].mn >= 0) ans++;
					else{
						modify(1, 0, ans, 1);
						break;
					}
				}
			}
			cout << ans << " ";
		}
		cout << "\n";
	}

	return 0;
}

