#include <bits/stdc++.h>
#define ll long long
using namespace std;
const int N = 3e5 + 10;
int n, m, QQ, tot, qcnt, ans[N], ls[N];
struct A{
	int l, r, c, k;
}ins[N];
struct Q{
	int a, lim;
	ll x;
	int id, ty;
}q[N], q1[N], q2[N];
struct Node{
	int l, r;
	ll a, b;
}tr[N << 2];
void pushdown(int u){
	ll c = tr[u].a, d = tr[u].b;
	tr[u << 1].a += c;
	tr[u << 1 | 1].a += c;
	tr[u << 1].b = max(tr[u << 1].b + c, d);
	tr[u << 1 | 1].b = max(tr[u << 1 | 1].b + c, d);
	tr[u].a = tr[u].b = 0;
}
void build(int u, int l, int r){
	tr[u] = {l, r, 0, 0};
	if(l == r) return;
	int mid = l + r >> 1;
	build(u << 1, l, mid);
	build(u << 1 | 1, mid + 1, r);
}
void modify(int u, int l, int r, ll a, ll b){
	if(l <= tr[u].l && tr[u].r <= r){
		tr[u].a += a;
		tr[u].b = max(tr[u].b + a, b);
		return;
	}
	int mid = tr[u].l + tr[u].r >> 1;
	pushdown(u);
	if(l <= mid) modify(u << 1, l, r, a, b);
	if(r > mid) modify(u << 1 | 1, l, r, a, b);
}
ll query(int u, int p){
	if(tr[u].l == tr[u].r) return max(tr[u].a, tr[u].b);
	int mid = tr[u].l + tr[u].r >> 1;
	pushdown(u);
	if(p <= mid) return query(u << 1, p);
	return query(u << 1 | 1, p);
}
ll B[N];
void add(int x, ll v){
	while(x <= n) B[x] += v, x += x & -x;
}
ll ask(int x){
	ll res = 0;
	while(x) res += B[x], x -= x & -x;
	return res;
}
ll BIT[N];
void ad(int x, ll v){
	while(x <= n) BIT[x] += v, x += x & -x;
}
ll as(int x){
	ll res = 0;
	while(x) res += BIT[x], x -= x & -x;
	return res;
}
void solve(int ql, int qr, int l, int r){
	if(ql > qr) return;
	if(l == r){
		for(int i = ql; i <= qr; i++)
			if(q[i].ty) ans[q[i].id] = ins[l].c;
		return;
	}
	int p1 = 0, p2 = 0, lscnt = 0, mid = l + r >> 1;
	for(int i = ql; i <= qr; i++){
		if(q[i].ty == 0){
			int id = q[i].id;
			if(id <= mid){
				ad(ins[id].l, ins[id].k);
				ad(ins[id].r + 1, -ins[id].k);
				ls[++lscnt] = id;
				q1[++p1] = q[i];
			}else q2[++p2] = q[i];
		}else{
			if(q[i].lim <= mid){
				q1[++p1] = q[i];
				continue;
			}
			ll c = as(q[i].a);
			if(q[i].x <= c) q1[++p1] = q[i];
			else{
				q[i].x -= c;
				q2[++p2] = q[i];
			}
		}
	}
	for(int i = 1; i <= lscnt; i++){
		int id = ls[i];
		ad(ins[id].l, -ins[id].k);
		ad(ins[id].r + 1, ins[id].k);
	}
	for(int i = 1; i <= p1; i++) q[ql + i - 1] = q1[i];
	for(int i = 1; i <= p2; i++) q[ql + p1 + i - 1] = q2[i];
	solve(ql, ql + p1 - 1, l, mid);
	solve(ql + p1, qr, mid + 1, r);
}
signed main(){
