	build(1, 1, n);
	int qid = 0;
	for(int i = 1; i <= QQ; i++){
		int op;
		cin >> op;
		if(op == 1){
			int l, r, c, k;
			cin >> l >> r >> c >> k;
			ins[++tot] = {l, r, c, k};
			modify(1, l, r, k, k);
			q[++qcnt] = {0, 0, 0, tot, 0};
			add(l, k);
			add(r + 1, -k);
		}else if(op == 2){
			int l, r, k;
			cin >> l >> r >> k;
			modify(1, l, r, -k, 0);
		}else{
            int a;
            ll b;
