            int id = ++qid;
            ll len = query(1, a);
            if(len >= b){
                ll x = ask(a) - len + b;
                q[++qcnt] = {a, tot, x, id, 1};
            }
		}
	}
	memset(BIT, 0, sizeof(BIT));
	solve(1, qcnt, 1, tot);
	for(int i = 1; i <= qid; i++) cout << ans[i] << '\n';
