int ans, R[N], L[N], n, h[N];
void solve(int ql, int qr, int l, int r){
	if(ql > qr) return;
	int mid = ql + qr >> 1;
	int mx = -1, pos = l;
	for(int i = l; i <= r; i++){
		if(R[i] < L[mid]) continue;
		int tmp = (R[i] - L[mid]) * (h[R[i]] + h[L[mid]]);
		if(tmp > mx) mx = tmp, pos = i;
	}
	ans = max(ans, mx);
	solve(ql, mid - 1, l, pos);
	solve(mid + 1, qr, pos, r);
} 
