bool bfs(){
	queue<int> q;
	q.push(s);
	memset(dep, -1, sizeof dep);
	dep[s] = 0;
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(auto v : e[u]){
			if(dep[v.to] == -1 && v.val){
				dep[v.to] = dep[u] + 1;
				q.push(v.to);				
			}
		}
	}
	memset(cur, 0, sizeof cur);
	return (dep[t] != -1);
}
int dfs(int u, int flow){
	if(u == t) return flow;
	int res = 0;
	for(int &i = cur[u]; i < e[u].size(); i++){
		Node v = e[u][i];
		if(dep[v.to] == dep[u] + 1 && v.val){
			int tmp = 0;
			tmp = dfs(v.to, min(flow - res, v.val));
			if(tmp){
				e[u][i].val -= tmp;
				e[v.to][v.rev].val += tmp;
				res += tmp;
				if(res == flow) break;		
			}else dep[v.to] = -1;
		}
	}
	return res;
}
