		for(int i = 0; i <= n; i++) vis[i] = cnt[i] = 0;
		build(1, 0, n);
		for(int i = 1; i <= n; i++){
			int x;
			cin >> x;
			if(x < ans && vis[x] == 0) modify(1, 0, x, 1), vis[x] = 1;
			else{
				if(x <= n) cnt[x]++;
				modify(1, 0, (x - 1) / 2, 1);
			} 
			while(ans <= i){
				if(vis[ans] == 1) ans++;
				else if(cnt[ans] >= 1){
					modify(1, 0, (ans - 1) / 2, -1);
					if(tr[1].mn >= 0) cnt[ans]--, vis[ans] = 1, ans++;
					else{
						modify(1, 0, (ans - 1) / 2, 1);
						break;
					}
				}else{
					modify(1, 0, ans, -1);
					if(tr[1].mn >= 0) ans++;
					else{
						modify(1, 0, ans, 1);
						break;
					}
				}
			}
			cout << ans << " ";
		}
