#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 3e5 + 10;
int n, k, b[N], cnt, sum[N];
bool cmp(int x, int y){
	return x > y;
}
bool check(int x, int k){
	if(x == 1) return 1;  
	return sum[x] < (k - x + 1) * b[x - 1];
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n;
	for(int i = 1; i <= n; i++){
		int x;
		cin >> x;
		if(!b[x]) cnt++;
		b[x] ++;
	}
	sort(b + 1, b + n + 1, cmp);
	for(int i = cnt; i >= 1; i--) sum[i] = sum[i + 1] + b[i];
	for(int k = 1; k <= n; k++){
		if(k > cnt) cout << 0 << "\n";
		else if(k == cnt) cout << b[cnt] << "\n";
		else{
			int l = 1, r = k, ans = 0;
			while(l <= r){
				int mid = l + r >> 1;
				if(check(mid, k)){
					ans = mid;
					l = mid + 1;
				}else{
					r = mid - 1;
				}
			}
			cout << sum[ans] / (k - ans + 1) << "\n";
		}
	}
	return 0;
}
