::::success[$\mathcal{O}(nlog^2n)$]
发现要求是一个三维偏序关系，考虑使用 cdq 分治优化（然后场上忘记 cdq 怎么写了痛失 30pts）。
首先可以发现只要按照从 $1$ 到 $n$ 的顺序把 $a$ 数组存下来就天然满足了 $j < i$ 的限制。每次分治时先递归处理左半边的部分，并顺便把左半边按照 $y$ 从小到大排好，此时我们对右半边按照 $y$ 从小到大额外进行一次排序，这样左右两边的 $y$ 都是有序的了。此时我们开两个指针 $pl,pr$，$pr$ 每次加一，$pl$ 都要不断加，并且把树状数组里处在 `a[pl].b` 位置的数和 `a[pl].dp - a[pl].t` 取 $\max$。当 $pl$ 不能再加时，此时树状数组中存储的就是所有满足 $j < i , y_j \le y_i$ 的数的 dp 值了，直接 `query(1, a[qr].b)` 即可。但是我们注意到还有一种转移是从 $i-1$ 转移过来的，我们考虑每一次递归完左半边之后，$[l,mid]$ 的 dp 值都已经唯一确定了，而 $[mid+1,r]$ 的都没有确定，所以此时有且仅有 $mid+1$ 的位置可以直接通过 上一个的 dp 值转移过来。复杂度是 $\mathcal{O}(nlog^2n)$ 的。


:::success[code]
```cpp
#include <bits/stdc++.h>
#define int long long
#define lowbit(x) x&-x
using namespace std;
const int N = 4e6 + 100, inf = 1e9;
int vis[N], idx, n;
int tr[N];
struct Node{
	int x, y, t, dp, id;
}a[N], ls[N];
void add(int x, int v){
	while(x <= N - 5){
		tr[x] = max(tr[x], v);
		x += lowbit(x);
	}
}
void cl(int x){
	while(x <= N - 5){
		tr[x] = -inf;
		x += lowbit(x);
	}
}
bool cmp(Node x, Node y){
	return x.x < y.x;
}
int query(int x){
	int res = -inf;
	while(x >= 1){
		res = max(tr[x], res);
		x -= lowbit(x);
	}
	return res;
}
void cdq(int l, int r){
	if(l == r) return;
	int mid = l + r >> 1;
	cdq(l, mid);
	int len = r - mid;
	for(int i = 1; i <= len; i++){
		ls[i] = a[mid + i];
		ls[i].id = mid + i;
	}
	sort(ls + 1, ls + len + 1, cmp);
	int pl = l, pr = 1;
	idx = 0;
	for(pr = 1; pr <= len; pr++){
		while(pl <= mid && a[pl].x <= ls[pr].x){
			add(a[pl].y, a[pl].dp - a[pl].t);
			vis[++idx] = a[pl].y;
			pl++;
		}
		ls[pr].dp = max(ls[pr].dp, query(ls[pr].y) + ls[pr].t);
	}
	for(int i = 1; i <= len; i++) a[ls[i].id].dp = ls[i].dp;
    for(int i = l; i <= mid; i++){
        if(a[i].id == mid){
            a[mid+1].dp = max(a[mid+1].dp, a[i].dp);
            break;
        }
    }
	for(int i = 1; i <= idx; i++) cl(vis[i]);
	cdq(mid + 1, r);
	pl = l, pr = mid + 1;
	int id = 0;
	while(pl <= mid && pr <= r){
		if(a[pl].x <= a[pr].x) ls[++id] = a[pl++];
		else ls[++id] = a[pr++];
	}
	while(pl <= mid) ls[++id] = a[pl++];
	while(pr <= r) ls[++id] = a[pr++];
	for(int i = 1; i <= id; i++) a[l + i - 1] = ls[i];
}
