#include <bits/stdc++.h>
#define eb emplace_back
using namespace std;
const int N = 5e3 + 10, mod = 998244353;
int n, K, dp[N][N][2], dep[N], mx_dep[N];
vector<int> e[N];
void dfs(int u, int fa){
	dp[u][0][0] = 1;
	dep[u] = dep[fa] + 1;
	mx_dep[u] = dep[u];
	for(auto v : e[u]){
		if(v == fa) continue;
		dfs(v, u);
	}
	for(auto k : e[u]){
		if(k == fa) continue;
		int sum = 0;
		for(int t = 0; t <= min(K, mx_dep[k] - dep[k]); t++) sum = (sum + dp[k][t][0]) % mod;
		for(int j = 0; j <= min(K, mx_dep[u] - dep[u]); j++){
			for(int t = 0; t <= min(K - j - 1, mx_dep[k] - dep[k]); t++){
				dp[u][max(t + 1, j)][1] = (dp[u][max(t + 1, j)][1] + 1LL * dp[u][j][0] * dp[k][t][0] % mod) % mod;
			}
			dp[u][j][1] = (dp[u][j][1] + 1LL * dp[u][j][0] * sum % mod) % mod;
		}
		for(int j = 0; j <= K; j++) dp[u][j][0] = dp[u][j][1], dp[u][j][1] = 0;
		mx_dep[u] = max(mx_dep[u], mx_dep[k]);
	}
}
signed main(){
