#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 3e5 + 10, mod = 1e9 + 7;
int inv[N], fac[N], f[N];
int ksm(int a, int b){
	int res = 1;
	while(b){
		if(b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}
void get_fac(){
	fac[0] = inv[0] = 1;
	for(int i = 1; i <= N - 5; i++) fac[i] = fac[i-1] * i % mod; 
	inv[N - 5] = ksm(fac[N-5], mod - 2);
	for(int i = N - 6; i >= 1; i--) inv[i] = inv[i+1] * (i+1) % mod;
}
int C(int a, int b){
	if(b < 0) return 0;
	if(b == 0) return 1;
	if(b > a) return 0;
	return fac[a] * inv[b] % mod * inv[a - b] % mod;
}
struct Node{
	int x, y;
}a[N];
bool cmp(Node x, Node y){
	if(x.x == y.x) return x.y < y.y;
	return x.x < y.x;
}
int js(Node a, Node b){
	return C(b.x - a.x + b.y - a.y, b.x - a.x);
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	get_fac();
	int r, c, n;
	cin >> r >> c >> n;
	for(int i = 1; i <= n; i++) cin >> a[i].x >> a[i].y;
	sort(a + 1, a + n + 1, cmp);
	Node s = {1, 1}, t = {r, c};
	int ans = js(s, t);
	for(int i = 1; i <= n; i++){
		f[i] = js(s, a[i]);
		for(int j = 1; j < i; j++){
			if(a[j].y > a[i].y) continue;
			f[i] = (f[i] - f[j] * js(a[j], a[i]) % mod + mod) % mod;
		}
		ans = (ans - f[i] * js(a[i], t) % mod + mod) % mod;
	}
	cout << (ans + mod) % mod;
	return 0;
}
