        for(int j = 0; j <= i; j++){
            int p = (a[i] - a[i - 1]) * j;
            for(int k = 0; k + p <= mx; k++){
                dp[i][j][k + p] = (dp[i][j][k + p] + dp[i - 1][j][k]) % mod;
                if(j) dp[i][j - 1][k + p] = (dp[i][j - 1][k + p] + 1LL * dp[i - 1][j][k] * j % mod) % mod;
                if(j < i) dp[i][j + 1][k + p] = (dp[i][j + 1][k + p] + dp[i - 1][j][k]) % mod;
                dp[i][j][k + p] = (dp[i][j][k + p] + 1LL * dp[i - 1][j][k] * j % mod) % mod;
            }
        }
    }
    int ans = 0;
    for(int k = 0; k <= mx; k++){
        ans = (ans + dp[n][0][k]) % mod;
    }
    cout << ans << "\n";
    return 0;
}
```
