#### [CF1942D](https://www.luogu.com.cn/problem/CF1942D)
其实挺简单的，不过被硬控了很长时间喵。  
先考虑弱化情况，即如果只要求找最大值应该怎么做，我们可以轻松列出以下转移：  
记 $dp_i$ 表示前 $i$ 个格子（不是必须选第 $i$ 个格子）能选出来的最大方案。  
$$
dp_i = \max(\max_{j=1}^{i} (dp_{\max(j-2,0)}+a_{j,i}),\ dp_{i-1})
$$
要求前 $k$ 大也类似，记 $dp_{i,rank}$ 表示前 $i$ 个格子（不是必须选第 $i$ 个格子）能选出来的第 $rank$ 大方案。暴力去做可以把所有 $dp_{\max(j-2,0),t} + a_{j,i}$ 和 $dp_{i-1,t}$ 扔进大根堆里，每次弹出堆顶获得第 $rank$ 大的方案。   
但是我们发现 $dp_i$ 虽然一共可能从 $\mathcal{O}(nk)$ 种状态转移过来，但是真正有用的只有前 $k$ 大的方案，考虑[多路归并](https://www.luogu.com.cn/problem/P1631)。因为 $dp_{\max(j-2,0),t+1} + a_{j,i}$ 一定在 $dp_{\max(j-2,0),t} + a_{j,i}$ 之后弹出，所以可以在弹出 $dp_{\max(j-2,0),t} + a_{j,i}$ 后再紧接着将 $dp_{\max(j-2,0),t+1} + a_{j,i}$  扔进堆里而不会影响答案。这样堆中只会有 $\mathcal{O}(k+n)$ 个元素，一共进行 $\mathcal{O}(k)$ 次操作，总复杂度 $\mathcal{O}(nk\log k)$。  
因为有负数情况，所以还要考虑一下初始化，初始一个格子也不选的情况的答案是 $0$，其余都是 $-inf$，即 $dp_{0,1}=0$。
::::success[code]
```cpp
#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 1100, inf = 1e15;
int n, r, a[N][N], dp[N][N * 5]; //前 i 个格子能凑出来的前 k 大美丽值
struct Node{
    int val;
    int id;
    int rk;
};
bool operator<(const Node &x, const Node &y){
    return x.val < y.val;
}
priority_queue<Node> q;
signed main(){
    int T;
    cin >> T;
    while(T--){
        cin >> n >> r;
        for(int i = 1; i <= n; i++) for(int j = i; j <= n; j++) cin >> a[i][j];
        for(int i = 0; i <= n + 5; i++) for(int k = 1; k <= r + 5; k++) dp[i][k] = -inf;
        dp[0][1] = 0;
        for(int i = 1; i <= n; i++){
            while(!q.empty()) q.pop();
            for(int k = 1; k <= r; k++) q.push(Node{dp[i - 1][k], 0, 114514});
            for(int j = 1; j <= i; j++) q.push(Node{dp[max(j - 2, 0LL)][1] + a[j][i], j, 1});
            for(int k = 1; k <= r; k++){
                Node tmp = q.top();
                q.pop();
                dp[i][k] = tmp.val;
                if(tmp.id) q.push(Node{dp[max(tmp.id - 2, 0LL)][tmp.rk + 1] + a[tmp.id][i], tmp.id, tmp.rk + 1});
            }
        }
        for(int k = 1; k <= r; k++) cout << dp[n][k] << " ";
        cout << "\n";
    }
    return 0;
}
